            if (*endptr != '\0') {
                // Invalid format, treat as regular arg
                if (subcommand == NULL) {
                    subcommand = arg;
                }
            }
        }
        // Check for subcommand
        else if (arg[0] != '-' && subcommand == NULL) {
            subcommand = arg;
        }
    }

    // Change directory if -C is specified
    if (start_path != NULL) {
        if (chdir(start_path) != 0) {
            fprintf(stderr, "tig: Failed to change directory to %s\n", start_path);
            return 1;
